import json
import sys


def handle(line):
    line = line.strip()
    if not line:
        return

    try:
        obj = json.loads(line)
    except (json.JSONDecodeError, ValueError):
        print(json.dumps({"accepted": False}, separators=(",", ":")))
        return

    if not isinstance(obj, dict):
        print(json.dumps({"accepted": False}, separators=(",", ":")))
        return

    if set(obj.keys()) != {"op", "from", "to"}:
        print(json.dumps({"accepted": False}, separators=(",", ":")))
        return

    op = obj["op"]
    frm = obj["from"]
    to = obj["to"]

    if not isinstance(op, str) or op != "transition":
        print(json.dumps({"accepted": False}, separators=(",", ":")))
        return

    if not isinstance(frm, str) or not isinstance(to, str):
        print(json.dumps({"accepted": False}, separators=(",", ":")))
        return

    if frm == "open" and to == "resolved":
        print(json.dumps({"accepted": True, "status": "resolved"}, separators=(",", ":")))
    else:
        print(json.dumps({"accepted": False, "status": frm}, separators=(",", ":")))


for line in sys.stdin:
    handle(line)
